    def parse_ws_trade(self, trade: dict, market: Market = None) -> Trade:
        #
        # public-trades
        #
        #     {
        #         "side": "buy",
        #         "price": 73797.26,
        #         "amount": 0.0015,
        #         "timestamp": 1794378421725
        #     }
        #
        # my-trades
        #
        #     {
        #         "id": "9adb20ae-f673-49a4-b232-75442e3af617",
        #         "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
        #         "timestamp": 1665997927993,
        #         "datetime": "2022-10-17T09:12:07.993Z",
        #         "symbol": "B2M/EUR",
        #         "order": "69d3df53-9248-430c-9850-d72ff1f0befa",
        #         "side": "sell",
        #         "price": 0.014,
        #         "amount": 100,
        #         "cost": 1.4,
        #         "fee": { "cost": 0.00224, "currency": "EUR", "rate": 0.16 },
        #         "isMaker": true,
        #         "clientOrderId": "MY-CLIENT-ORDER-ID"
        #     }
        #
        marketId = self.safe_string(trade, 'symbol')
        resolvedMarket = self.safe_market(marketId, market)
        timestamp = self.safe_integer(trade, 'timestamp')
        isMaker = self.safe_bool(trade, 'isMaker')
        takerOrMaker = None
        if isMaker is not None:
            takerOrMaker = 'maker' if (isMaker) else 'taker'
        fee = None
        rawFee = self.safe_dict(trade, 'fee')
        if rawFee is not None:
            feeRate = None
            feePercentage = self.safe_string(rawFee, 'rate')
            if feePercentage is not None:
                feeRate = Precise.string_div(feePercentage, '100')
            fee = {
                'cost': self.safe_string(rawFee, 'cost'),
                'currency': self.safe_currency_code(self.safe_string(rawFee, 'currency')),
                'rate': feeRate,
            }
        return self.safe_trade({
            'info': trade,
            'id': self.safe_string(trade, 'id'),
            'symbol': resolvedMarket['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'order': self.safe_string(trade, 'order'),
            'type': None,
            'side': self.safe_string_lower(trade, 'side'),
            'takerOrMaker': takerOrMaker,
            'price': self.safe_string(trade, 'price'),
            'amount': self.safe_string(trade, 'amount'),
            'cost': self.safe_string(trade, 'cost'),
            'fee': fee,
        }, resolvedMarket)

